async function* readArchive(chunks) {
  const iterator = chunks[Symbol.asyncIterator]();
  const decoder = new TextDecoder("utf-8");
  let sourceDone = false;
  let failed = false;
  let text = "";
  let offset = 0;
  let lineNumber = 1;
  let parts = [];

  function parseRecord(line, number) {
    try {
      return JSON.parse(line);
    } catch {
      const error = new SyntaxError(`Invalid JSON on line ${number}`);
      error.code = "INVALID_RECORD";
      error.line = number;
      throw error;
    }
  }

  try {
    while (true) {
      const newline = text.indexOf("\n", offset);

      if (newline !== -1) {
        const segment = text.slice(offset, newline);
        const line = parts.length
          ? (parts.push(segment), parts.join(""))
          : segment;

        parts = [];
        offset = newline + 1;
        const number = lineNumber++;

        if (line.trim() !== "") {
          yield parseRecord(line, number);
        }
        continue;
      }

      if (offset < text.length) {
        parts.push(text.slice(offset));
      }
      text = "";
      offset = 0;

      if (sourceDone) {
        const line = parts.join("");
        parts = [];
        if (line.trim() !== "") {
          yield parseRecord(line, lineNumber);
        }
        return;
      }

      const result = await iterator.next();
      if (result.done) {
        sourceDone = true;
        text = decoder.decode();
      } else {
        text = decoder.decode(result.value, { stream: true });
      }
    }
  } catch (error) {
    failed = true;
    throw error;
  } finally {
    if (!sourceDone) {
      try {
        const close = iterator.return;
        if (close != null) {
          await close.call(iterator);
        }
      } catch (error) {
        if (!failed) throw error;
      }
    }
  }
}
